package com.rezkery.randomizer;

import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.*;
import android.webkit.*;
import android.widget.*;
import android.view.*;
import org.json.*;
import java.io.*;
import java.net.URL;
import java.net.HttpURLConnection;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** The bridge exists only on the bundled HTTPS origin, never on an HDRezka page. */
public class SuiteActivity extends Activity {
    static final String HOME="https://suite.rezkery.invalid/suite/index.html";
    WebView view,site;LinearLayout root,siteBox;SuiteDatabase database;Handler handler=new Handler(Looper.getMainLooper());
    ValueCallback<Uri[]> chooser;File exportFile;OutputStream exportStream;String exportName,exportType;String activeId;JSONObject activeCommand;int polls;boolean loadingSite;
    @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);database=new SuiteDatabase(this);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setFitsSystemWindows(true);setContentView(root);
        view=new WebView(this);view.getSettings().setJavaScriptEnabled(true);view.getSettings().setDomStorageEnabled(true);view.getSettings().setAllowFileAccess(false);view.getSettings().setAllowContentAccess(true);view.addJavascriptInterface(new Bridge(),"RezkaNative");
        view.setWebViewClient(new WebViewClient(){
            @Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){Uri u=r.getUrl();if(!"suite.rezkery.invalid".equals(u.getHost()))return null;String path=u.getPath();if(path==null||!path.startsWith("/suite/")||path.contains(".."))return new WebResourceResponse("text/plain","UTF-8",403,"Forbidden",Collections.emptyMap(),new ByteArrayInputStream(new byte[0]));String name=path.substring(7),mime=name.endsWith(".html")?"text/html":name.endsWith(".css")?"text/css":"application/javascript";try{return new WebResourceResponse(mime,"UTF-8",getAssets().open(name));}catch(Exception e){return new WebResourceResponse("text/plain","UTF-8",404,"Not found",Collections.emptyMap(),new ByteArrayInputStream(new byte[0]));}}
            @Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){if(r.getUrl().toString().startsWith(HOME))return false;openExternal(r.getUrl().toString());return true;}
        });
        view.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> callback,FileChooserParams params){if(chooser!=null)chooser.onReceiveValue(null);chooser=callback;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,201);return true;}});
        root.addView(view,new LinearLayout.LayoutParams(-1,0,1));view.loadUrl(HOME);
    }
    void openExternal(String value){try{Uri u=Uri.parse(value);if(!"https".equals(u.getScheme())&&!"http".equals(u.getScheme()))return;startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception e){Toast.makeText(this,"Не удалось открыть ссылку",Toast.LENGTH_SHORT).show();}}
    String asset(String name)throws IOException{try(InputStream in=getAssets().open(name);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}}
    void ensureSite(){if(site!=null)return;siteBox=new LinearLayout(this);siteBox.setOrientation(LinearLayout.VERTICAL);Button back=new Button(this);back.setText("Вернуться в библиотеку");back.setOnClickListener(v->{siteBox.setVisibility(View.GONE);view.setVisibility(View.VISIBLE);});siteBox.addView(back);site=new WebView(this);site.setFocusable(true);site.setFocusableInTouchMode(true);site.getSettings().setJavaScriptEnabled(true);site.getSettings().setDomStorageEnabled(true);site.getSettings().setUseWideViewPort(true);site.getSettings().setLoadWithOverviewMode(true);site.getSettings().setBuiltInZoomControls(true);site.getSettings().setDisplayZoomControls(false);site.getSettings().setUserAgentString(site.getSettings().getUserAgentString().replace("; wv",""));CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(site,true);site.setWebChromeClient(new WebChromeClient());
        site.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !"https".equals(r.getUrl().getScheme());}@Override public void onPageFinished(WebView v,String u){CookieManager.getInstance().flush();if(loadingSite&&activeId!=null){loadingSite=false;executeSite();}}});siteBox.addView(site,new LinearLayout.LayoutParams(-1,0,1));root.addView(siteBox,new LinearLayout.LayoutParams(-1,0,1));siteBox.setVisibility(View.GONE);
    }
    void showLogin(String u){ensureSite();siteBox.setVisibility(View.VISIBLE);view.setVisibility(View.GONE);site.requestFocus();site.loadUrl(u);}
    void reply(String id,JSONObject result){if(isFinishing()||view==null)return;view.evaluateJavascript("window.suiteNativeReply&&window.suiteNativeReply("+JSONObject.quote(id)+","+result+")",null);}
    void error(String id,String text){try{reply(id,new JSONObject().put("error",text));}catch(Exception ignored){}}
    void request(String id,JSONObject command){if(activeId!=null){error(id,"Предыдущий запрос ещё выполняется");return;}activeId=id;activeCommand=command;polls=0;
        if(command.optString("op").equals("image")){new Thread(()->{JSONObject out=new JSONObject();HttpURLConnection connection=null;try{URL u=new URL(command.getString("url"));if(!u.getProtocol().equals("https"))throw new Exception("Нужен HTTPS-постер");connection=(HttpURLConnection)u.openConnection();connection.setConnectTimeout(20000);connection.setReadTimeout(25000);int code=connection.getResponseCode();if(code==429){out.put("retryAfter",connection.getHeaderField("Retry-After")==null?"60":connection.getHeaderField("Retry-After"));out.put("error","HTTP 429");}else{String type=connection.getContentType().split(";")[0];if(code!=200||!type.matches("image/(png|jpeg|webp|gif)"))throw new Exception("Сайт не вернул постер: HTTP "+code);try(InputStream in=connection.getInputStream();ByteArrayOutputStream bytes=new ByteArrayOutputStream()){byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1){bytes.write(b,0,n);if(bytes.size()>10*1024*1024)throw new Exception("Постер больше 10 МБ");}out.put("data","data:"+type+";base64,"+android.util.Base64.encodeToString(bytes.toByteArray(),android.util.Base64.NO_WRAP));}}}catch(Exception e){try{out.put("error",e.getMessage());}catch(Exception ignored){}}finally{if(connection!=null)connection.disconnect();}handler.post(()->{reply(id,out);activeId=null;});}).start();return;}
        ensureSite();String target=command.optString("op").equals("capture")?command.optString("url"):command.optString("origin")+"/favorites/";try{if(!new URL(target).getProtocol().equals("https"))throw new Exception("Используйте HTTPS");}catch(Exception e){error(id,"Некорректный адрес зеркала");activeId=null;return;}
        if(command.optString("op").equals("capture")||site.getUrl()==null||!site.getUrl().startsWith(command.optString("origin")+"/")){loadingSite=true;site.loadUrl(target);handler.postDelayed(()->{if(id.equals(activeId)&&loadingSite){site.stopLoading();loadingSite=false;activeId=null;error(id,"Таймаут страницы HDRezka");}},35000);}else executeSite();
    }
    void executeSite(){try{String script=asset("core.js")+"\n"+asset("site.js")+"\nwindow.__suiteResult=null;RezkaSite.run("+activeCommand+").then(x=>{window.__suiteResult=JSON.stringify(x)});true;";site.evaluateJavascript(script,v->handler.postDelayed(this::poll,250));}catch(Exception e){error(activeId,e.getMessage());activeId=null;}}
    void poll(){if(activeId==null)return;if(++polls>120){error(activeId,"Таймаут ответа HDRezka");activeId=null;return;}site.evaluateJavascript("window.__suiteResult",value->{try{Object decoded=new JSONTokener(value==null?"null":value).nextValue();if(decoded==JSONObject.NULL){handler.postDelayed(this::poll,500);return;}JSONObject result=new JSONObject(String.valueOf(decoded));String id=activeId;activeId=null;if(result.optBoolean("challenge")||result.optBoolean("login")){siteBox.setVisibility(View.VISIBLE);view.setVisibility(View.GONE);}reply(id,result);}catch(Exception e){error(activeId,"Не удалось прочитать ответ сайта");activeId=null;}});}
    final class Bridge {
        @JavascriptInterface public String database(String input){JSONObject out=new JSONObject();try{Object value=database.command(new JSONObject(input));out.put("value",value==null?JSONObject.NULL:value);}catch(Exception e){try{out.put("error",e.getMessage()==null?"Ошибка базы":e.getMessage());}catch(Exception ignored){}}return out.toString();}
        @JavascriptInterface public void request(String id,String data){handler.post(()->{try{SuiteActivity.this.request(id,new JSONObject(data));}catch(Exception e){error(id,e.getMessage());}});}
        @JavascriptInterface public void open(String u){handler.post(()->openExternal(u));}
        @JavascriptInterface public void login(String u){handler.post(()->showLogin(u));}
        @JavascriptInterface public String legacy(){return getSharedPreferences("rzk",0).getString("library","[]");}
        @JavascriptInterface public void selected(String input){try{android.content.SharedPreferences p=getSharedPreferences("rzk",0);JSONArray old=new JSONArray(p.getString("library","[]")),incoming=new JSONArray(input),used=new JSONArray(p.getString("used","[]"));Map<String,JSONObject> merged=new LinkedHashMap<>();for(int i=0;i<old.length();i++){JSONObject m=old.getJSONObject(i);merged.put(cardId(m),m);}for(int i=0;i<incoming.length();i++){JSONObject m=incoming.getJSONObject(i);merged.put(cardId(m),m);used.put(Uri.parse(m.optString("url")).getPath());}JSONArray list=new JSONArray();for(JSONObject m:merged.values())list.put(m);p.edit().putString("library",list.toString()).putString("used",used.toString()).apply();}catch(Exception ignored){}}
        @JavascriptInterface public synchronized void beginExport(String name,String type)throws IOException{cancelExport();exportName=name;exportType=type;exportFile=File.createTempFile("suite-export-",".tmp",getCacheDir());exportStream=new FileOutputStream(exportFile);}
        @JavascriptInterface public synchronized void exportChunk(String data)throws IOException{if(exportStream==null)throw new IOException("Экспорт не начат");exportStream.write(android.util.Base64.decode(data,android.util.Base64.DEFAULT));}
        @JavascriptInterface public synchronized void finishExport()throws IOException{if(exportStream==null)return;exportStream.close();exportStream=null;handler.post(()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(exportType);i.putExtra(Intent.EXTRA_TITLE,exportName);startActivityForResult(i,202);});}
        @JavascriptInterface public synchronized void cancelExport(){try{if(exportStream!=null)exportStream.close();}catch(Exception ignored){}exportStream=null;if(exportFile!=null)exportFile.delete();exportFile=null;}
    }
    String cardId(JSONObject m){String path=Uri.parse(m.optString("url")).getPath();if(path==null)return m.optString("id");java.util.regex.Matcher matcher=java.util.regex.Pattern.compile("/(\\d+)-[^/]+$").matcher(path);return matcher.find()?matcher.group(1):path;}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==201&&chooser!=null){chooser.onReceiveValue(result==RESULT_OK&&data!=null?new Uri[]{data.getData()}:null);chooser=null;}if(request==202){File file=exportFile;exportFile=null;if(result==RESULT_OK&&data!=null&&file!=null){Uri destination=data.getData();new Thread(()->{try(InputStream in=new FileInputStream(file);OutputStream out=getContentResolver().openOutputStream(destination)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);handler.post(()->Toast.makeText(this,"Копия сохранена",Toast.LENGTH_LONG).show());}catch(Exception e){handler.post(()->Toast.makeText(this,"Не удалось сохранить копию",Toast.LENGTH_LONG).show());}finally{file.delete();}}).start();}else if(file!=null)file.delete();}}
    @Override public void onBackPressed(){if(siteBox!=null&&siteBox.getVisibility()==View.VISIBLE){siteBox.setVisibility(View.GONE);view.setVisibility(View.VISIBLE);}else super.onBackPressed();}
    @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);if(chooser!=null)chooser.onReceiveValue(null);new Bridge().cancelExport();if(site!=null)site.destroy();if(view!=null)view.destroy();database.close();super.onDestroy();}
}
